import {useMemo,useState} from 'react';
import {Alert,Platform,Pressable,Share,StyleSheet,Text,useWindowDimensions,View} from '@/platform/react-native';
import {router,useLocalSearchParams} from '@/router';
import {useMutation,useQuery,useQueryClient} from '@tanstack/react-query';
import {Ionicons} from '@/platform/icons';
import * as DocumentPicker from '@/platform/document-picker';
import * as ImagePicker from '@/platform/image-picker';
import {api} from '@/lib/api';
import {Button,Card,Header,Input,Muted,Screen,useAppTheme} from '@/components/UI';


const categories=['Constitution','Policies','Meeting minutes','Financial reports','Forms','Newsletters','Community rules','Emergency procedures','Archives','Other'] as const;
type Category=typeof categories[number];
type Doc={Id:string;Category:string;Title:string;Summary?:string;Visibility:'MEMBERS'|'ADMINS';CurrentVersion:number;UpdatedAt:string;UploadedAt?:string;FileName?:string;MimeType?:string;SizeBytes?:number;UploaderFirstName?:string;UploaderLastName?:string};
type Upload={uri:string;name:string;mimeType:string;file?:File;size?:number};
type Group={key:string;label:string;icon:keyof typeof Ionicons.glyphMap;categories?:Category[];color:string;background:string};
const groups:Group[]=[
 {key:'All',label:'All Documents',icon:'folder-outline',color:'#149447',background:'#EAF7EE'},
 {key:'Policies',label:'Policies',icon:'document-text-outline',categories:['Policies','Constitution','Community rules'],color:'#2374EA',background:'#EAF1FF'},
 {key:'Reports',label:'Reports',icon:'people-outline',categories:['Meeting minutes','Financial reports','Newsletters'],color:'#8B4DE8',background:'#F2EAFE'},
 {key:'Forms',label:'Forms',icon:'reader-outline',categories:['Forms'],color:'#F28A00',background:'#FFF2DF'},
 {key:'Archives',label:'Archives',icon:'archive-outline',categories:['Archives'],color:'#08979C',background:'#E7F6F6'},
];
const supportedExtensions=['pdf','doc','docx','xls','xlsx','ppt','pptx','txt','csv','jpg','jpeg','png','gif','webp','mp4','mov','m4a','mp3','wav'] as const;const maxUploadBytes=25*1024*1024;
const ext=(value?:string)=>value?.split('?')[0].split('.').pop()?.toUpperCase()||'FILE';
const size=(value?:number)=>!value?'':value<1048576?`${(value/1024).toFixed(1)} KB`:`${(value/1048576).toFixed(1)} MB`;
function docIcon(doc:Partial<Doc>):keyof typeof Ionicons.glyphMap{const value=ext(doc.FileName);if(value==='PDF')return'document-text-outline';if(['DOC','DOCX'].includes(value))return'document-outline';if(['XLS','XLSX','CSV'].includes(value))return'grid-outline';if(['PPT','PPTX'].includes(value))return'easel-outline';if(['JPG','JPEG','PNG','GIF','WEBP'].includes(value))return'image-outline';if(['MP4','MOV'].includes(value))return'videocam-outline';if(['MP3','WAV','M4A'].includes(value))return'musical-notes-outline';return'document-attach-outline'}

export default function Documents(){
 const{id,group,create}=useLocalSearchParams<{id:string;group?:string;create?:string}>();const{palette}=useAppTheme();const{width}=useWindowDimensions();const qc=useQueryClient();
 const initialGroup=groups.some(item=>item.key===group)?String(group):'All';const[search,setSearch]=useState('');const[filter,setFilter]=useState(initialGroup);const[showAll,setShowAll]=useState(initialGroup!=='All');const[form,setForm]=useState(create==='1');const[file,setFile]=useState<Upload|null>(null);const[title,setTitle]=useState('');const[summary,setSummary]=useState('');const[category,setCategory]=useState<Category>('Policies');const[visibility,setVisibility]=useState<'MEMBERS'|'ADMINS'>('MEMBERS');const[progress,setProgress]=useState(0);const[controller,setController]=useState<AbortController|null>(null);
 const docs=useQuery<Doc[]>({queryKey:['documents',id],queryFn:async()=>(await api.get(`/communities/${id}/documents`)).data});
 const capabilities=useQuery<any>({queryKey:['capabilities',id],queryFn:async()=>(await api.get(`/communities/${id}/capabilities`)).data});
 const canManage=!!capabilities.data?.permissions?.includes('DOCUMENT_MANAGE')||!!capabilities.data?.isOwner||!!capabilities.data?.canManageCommunity;
 const count=(group:Group)=>(docs.data||[]).filter(d=>!group.categories||group.categories.some(category=>category===d.Category)).length;
 const shown=useMemo(()=>{const group=groups.find(g=>g.key===filter);const q=search.trim().toLowerCase();return(docs.data||[]).filter(d=>(!group?.categories||group.categories.some(category=>category===d.Category))&&(!q||`${d.Title} ${d.Summary||''} ${d.Category} ${d.FileName||''}`.toLowerCase().includes(q)))},[docs.data,filter,search]);
 const visible=showAll||filter!=='All'||!!search?shown:shown.slice(0,5);
 function accept(item:any){const extension=String(item.name||item.fileName||'').split('.').pop()?.toLowerCase();if(!extension||!supportedExtensions.includes(extension as any))return Alert.alert('Unsupported file',`Supported types: ${supportedExtensions.join(', ').toUpperCase()}`);if(item.size||item.fileSize){const bytes=item.size||item.fileSize;if(bytes>maxUploadBytes)return Alert.alert('File too large','Maximum upload size is 25 MB.')}const name=item.name||item.fileName||`photo-${Date.now()}.jpg`;setFile({uri:item.uri,name,mimeType:item.mimeType||'image/jpeg',file:item.file,size:item.size||item.fileSize});if(!title)setTitle(name.replace(/\.[^.]+$/,''))}
 async function browseFiles(){const result=await DocumentPicker.getDocumentAsync({type:['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation','text/plain','text/csv','image/jpeg','image/png','image/gif','image/webp','video/mp4','video/quicktime','audio/mp4','audio/mpeg','audio/wav'],copyToCacheDirectory:true});if(!result.canceled)accept(result.assets[0])}
 async function choosePhoto(){const permission=await ImagePicker.requestMediaLibraryPermissionsAsync();if(!permission.granted)return Alert.alert('Photo access required','Allow photo access to choose an image.');const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],quality:.9});if(!result.canceled)accept(result.assets[0])}
 async function choose(){if(Platform.OS==='web')return browseFiles();Alert.alert('Choose upload type','Select where the file should come from.',[{text:'Photo library',onPress:()=>void choosePhoto()},{text:'Files and documents',onPress:()=>void browseFiles()},{text:'Cancel',style:'cancel'}])}
 const upload=useMutation({mutationFn:async()=>{if(!file)throw new Error('Choose a file');if(file.size&&file.size>maxUploadBytes)throw new Error('Maximum upload size is 25 MB.');const abort=new AbortController();setController(abort);setProgress(0);const data=new FormData();if(Platform.OS==='web'){const selected=file.file||new File([await(await fetch(file.uri)).blob()],file.name,{type:file.mimeType});data.append('file',selected)}else data.append('file',{uri:file.uri,name:file.name,type:file.mimeType} as any);let storedObjectId:string|undefined;try{const stored=(await api.post(`/media/upload?purpose=document&communityId=${id}`,data,{headers:{'Content-Type':'multipart/form-data'},signal:abort.signal,onUploadProgress:event=>setProgress(event.total?Math.round(event.loaded/event.total*100):0)})).data;storedObjectId=stored.storedObjectId;return await api.post(`/communities/${id}/documents`,{storedObjectId,category,title:title.trim(),summary:summary.trim()||undefined,visibility,changeNotes:'Initial upload'},{signal:abort.signal})}catch(error){if(storedObjectId)await api.delete(`/media/uploads/${storedObjectId}`).catch(()=>{});throw error}finally{setController(null)}},onSuccess:()=>{qc.invalidateQueries({queryKey:['documents',id]});setForm(false);setFile(null);setTitle('');setSummary('');setProgress(0);Alert.alert('Document uploaded','The file is now available to authorised community members.')},onError:(error:any)=>Alert.alert(error.code==='ERR_CANCELED'?'Upload cancelled':'Upload failed',error.code==='ERR_CANCELED'?'The upload was cancelled.':error.response?.data?.error||error.response?.data?.message||error.message)});
 async function open(doc:Doc){router.push({pathname:`/community/${id}/document/${doc.Id}` as any,params:{title:doc.Title}})}
 async function share(doc:Doc){try{const result=(await api.post(`/documents/${doc.Id}/share-link`)).data;await Share.share({title:doc.Title,message:result.path})}catch(error:any){Alert.alert('Unable to share',error.response?.data?.error||'Your access may have changed.')}}
 function options(doc:Doc){const actions:any[]=[{text:'Open',onPress:()=>void open(doc)}];if(doc.Visibility==='MEMBERS')actions.push({text:'Share internal link',onPress:()=>void share(doc)});actions.push({text:'Cancel',style:'cancel'});Alert.alert(doc.Title,undefined,actions)}
 function selectGroup(key:string){setFilter(key);setShowAll(true)}
 if(form)return <Screen scroll contentStyle={s.form}><Header title="Upload Document" subtitle="Publish an authorised community file" right={<Pressable disabled={upload.isPending} accessibilityLabel="Close upload" onPress={()=>setForm(false)} style={s.touch}><Ionicons name="close" size={24} color={palette.text}/></Pressable>}/><Muted>Maximum size: 25 MB. Supported: {supportedExtensions.join(', ').toUpperCase()}.</Muted><Pressable disabled={upload.isPending} accessibilityRole="button" accessibilityLabel="Choose document file" onPress={()=>void choose()} style={[s.picker,{borderColor:palette.primary}]}><Ionicons name={file?docIcon({FileName:file.name}):'cloud-upload-outline'} size={30} color={palette.primary}/><View style={s.flex}><Text numberOfLines={1} style={[s.fileName,{color:palette.text}]}>{file?.name||'Choose a file'}</Text><Muted>{file?`${ext(file.name)}${file.size?` · ${size(file.size)}`:''}`:'Select a supported file type'}</Muted></View></Pressable><Input placeholder="Document title" value={title} onChangeText={setTitle}/><Input placeholder="Description (optional)" value={summary} onChangeText={setSummary} multiline/><Text style={[s.label,{color:palette.text}]}>Category</Text><View style={s.choices}>{categories.map(value=><Pressable accessibilityRole="radio" accessibilityState={{selected:category===value}} accessibilityLabel={`Category ${value}`} disabled={upload.isPending} key={value} onPress={()=>setCategory(value)} style={[s.choice,{borderColor:category===value?palette.primary:palette.border}]}><Ionicons name={category===value?'checkmark-circle':'ellipse-outline'} size={17} color={category===value?palette.primary:palette.muted}/><Text style={[s.choiceText,{color:palette.text}]}>{value}</Text></Pressable>)}</View><Text style={[s.label,{color:palette.text}]}>Visibility</Text><View style={s.visibility}><Button title="All Members" icon="people-outline" variant={visibility==='MEMBERS'?'primary':'secondary'} disabled={upload.isPending} onPress={()=>setVisibility('MEMBERS')}/><Button title="Admins Only" icon="shield-outline" variant={visibility==='ADMINS'?'primary':'secondary'} disabled={upload.isPending} onPress={()=>setVisibility('ADMINS')}/></View>{upload.isPending?<><Muted>Uploading… {progress}%</Muted><View style={[s.progressTrack,{backgroundColor:palette.border}]}><View style={[s.progress,{backgroundColor:palette.primary,width:`${progress}%`}]} /></View><Button title="Cancel upload" variant="secondary" onPress={()=>controller?.abort()}/></>:<Button title="Upload Document" icon="cloud-upload-outline" disabled={!file||title.trim().length<2} onPress={()=>upload.mutate()}/>}</Screen>;
 return <Screen scroll contentStyle={s.page}><Header page title="Document Center"/>
  <View style={[s.hero,{backgroundColor:palette.primaryDark}]}><View style={s.flex}><Text style={s.heroTitle}>All community documents,{`\n`}organised and easy to access.</Text><Text style={s.heroMeta}>⌾  Secure  •  Organised  •  Always Available</Text></View><View style={s.heroArt}><Ionicons name="folder-open" size={42} color="#BFEBCB"/></View></View>
  <Card style={s.summary}>{groups.map((group,index)=><Pressable key={group.key} onPress={()=>selectGroup(group.key)} style={[s.summaryItem,index>0&&{borderLeftWidth:1,borderLeftColor:palette.border}]}><View style={[s.summaryIcon,{backgroundColor:group.background}]}><Ionicons name={group.icon} size={21} color={group.color}/></View><Text numberOfLines={2} style={[s.summaryLabel,{color:palette.text}]}>{group.label}</Text><View style={[s.countPill,{backgroundColor:'#EAF7EE'}]}><Text style={[s.countText,{color:palette.primary}]}>{count(group)}</Text></View></Pressable>)}</Card>
  <View style={[s.search,{borderColor:palette.border}]}><Ionicons name="search-outline" size={20} color={palette.muted}/><Input value={search} onChangeText={setSearch} placeholder="Search documents" style={s.searchInput}/>{search?<Pressable accessibilityLabel="Clear search" onPress={()=>setSearch('')} style={s.touch}><Ionicons name="close-circle" size={20} color={palette.muted}/></Pressable>:null}</View>
  <View style={s.heading}><Text style={[s.sectionTitle,{color:palette.text}]}>{filter==='All'&&!search?'Recent Documents':groups.find(g=>g.key===filter)?.label||'Documents'}</Text>{shown.length>visible.length?<Pressable onPress={()=>setShowAll(true)} style={s.inlineButton}><Text style={[s.viewAll,{color:palette.primary}]}>View all</Text><Ionicons name="chevron-forward" size={16} color={palette.primary}/></Pressable>:<Muted>{shown.length} {shown.length===1?'file':'files'}</Muted>}</View>
  {docs.isLoading?<Muted style={s.loading}>Loading documents…</Muted>:docs.isError?<CompactEmpty icon="cloud-offline-outline" title="Documents unavailable" body="The community documents could not be loaded." palette={palette}/>:visible.length?<Card style={s.list}>{visible.map((doc,index)=><Pressable accessibilityRole="button" accessibilityLabel={`Open ${doc.Title}`} key={doc.Id} onPress={()=>void open(doc)} style={[s.row,index<visible.length-1&&{borderBottomWidth:1,borderBottomColor:palette.border}]}><View style={[s.docIcon,{backgroundColor:'#F4F8F5'}]}><Ionicons name={docIcon(doc)} size={22} color={palette.primary}/></View><View style={s.flex}><Text numberOfLines={1} style={[s.docTitle,{color:palette.text}]}>{doc.Title}</Text><Muted numberOfLines={1}>{doc.Category||'Other'}  •  {ext(doc.FileName)}{doc.SizeBytes?`  •  ${size(doc.SizeBytes)}`:''}</Muted><View style={[s.badge,{backgroundColor:doc.Visibility==='ADMINS'?'#FFF2DF':'#EAF7EE'}]}><Text style={{fontSize:10,fontWeight:'800',color:doc.Visibility==='ADMINS'?'#A35B00':palette.primary}}>{doc.Visibility==='ADMINS'?'Admins only':'Members'}</Text></View></View><View style={s.date}><Muted>{new Date(doc.UpdatedAt).toLocaleDateString([], {month:'short',day:'numeric',year:'numeric'})}</Muted>{doc.UploaderFirstName?<Muted numberOfLines={1}>{doc.UploaderFirstName} {doc.UploaderLastName}</Muted>:null}</View><Pressable accessibilityLabel={`Options for ${doc.Title}`} onPress={event=>{event.stopPropagation();options(doc)}} style={s.touch}><Ionicons name="ellipsis-vertical" size={18} color={palette.muted}/></Pressable></Pressable>)}</Card>:<CompactEmpty icon="folder-open-outline" title={search?'No matching documents':'No documents yet'} body={canManage?'Upload the first community document.':'Published community documents will appear here.'} palette={palette}/>}
  {capabilities.isLoading?<Muted>Checking document permissions…</Muted>:capabilities.isError?<Muted>Document management controls could not be loaded.</Muted>:canManage?<Pressable accessibilityRole="button" accessibilityLabel="Upload a community document" onPress={()=>setForm(true)} style={[s.upload,{borderColor:palette.border,backgroundColor:'#F6FBF7'}]}><View style={[s.uploadIcon,{backgroundColor:'#E5F5E9'}]}><Ionicons name="cloud-upload-outline" size={25} color={palette.primary}/></View><View style={s.flex}><Text style={[s.uploadTitle,{color:palette.primary}]}>Upload Document</Text><Muted>Share documents with your community</Muted></View><View style={[s.uploadButton,{borderColor:palette.primary}]}><Ionicons name="share-outline" size={17} color={palette.primary}/><Text style={[s.uploadButtonText,{color:palette.primary}]}>Upload</Text></View></Pressable>:null}
  <Card style={s.categories}><View style={s.heading}><Text style={[s.sectionTitle,{color:palette.text}]}>Categories</Text><Pressable accessibilityRole="button" accessibilityLabel="View all document folders" onPress={()=>router.push(`/community/${id}/document-folders` as any)}><Text style={[s.viewAll,{color:palette.primary}]}>View all</Text></Pressable></View><View style={s.categoryGrid}>{groups.slice(1).map(group=><Pressable key={group.key} onPress={()=>selectGroup(group.key)} style={[s.categoryCard,{borderColor:palette.border,width:width<430?'48%':'23%'}]}><View style={[s.summaryIcon,{backgroundColor:group.background}]}><Ionicons name={group.icon} size={21} color={group.color}/></View><Text style={[s.categoryTitle,{color:palette.text}]}>{group.label}</Text><Muted>{count(group)} documents</Muted><View style={[s.progressTrack,{backgroundColor:palette.border}]}><View style={[s.progress,{backgroundColor:group.color,width:`${Math.min(100,Math.max(count(group)?12:0,(count(group)/Math.max(1,docs.data?.length||0))*100))}%`}]} /></View></Pressable>)}</View></Card>
</Screen>;
}
function CompactEmpty({icon,title,body,palette}:{icon:keyof typeof Ionicons.glyphMap;title:string;body:string;palette:any}){return <Card style={s.empty}><Ionicons name={icon} size={34} color={palette.primary}/><View style={s.flex}><Text style={[s.emptyTitle,{color:palette.text}]}>{title}</Text><Muted>{body}</Muted></View></Card>}
const s=StyleSheet.create({page:{width:'100%',maxWidth:900,alignSelf:'center',paddingBottom:125,gap:12},form:{width:'100%',maxWidth:720,alignSelf:'center',paddingBottom:40},flex:{flex:1,minWidth:0},touch:{width:38,height:38,alignItems:'center',justifyContent:'center'},hero:{minHeight:116,borderRadius:18,paddingHorizontal:18,paddingVertical:16,flexDirection:'row',alignItems:'center',gap:10},heroTitle:{color:'#fff',fontSize:17,lineHeight:24,fontWeight:'800'},heroMeta:{color:'#D9FBE7',fontSize:10.5,fontWeight:'700',marginTop:11},heroArt:{width:64,alignItems:'center'},summary:{paddingVertical:10,paddingHorizontal:2,flexDirection:'row',overflow:'hidden'},summaryItem:{flex:1,minWidth:0,alignItems:'center',justifyContent:'center',paddingHorizontal:3,gap:4},summaryIcon:{width:38,height:38,borderRadius:12,alignItems:'center',justifyContent:'center'},summaryLabel:{fontSize:10.5,lineHeight:13,fontWeight:'700',textAlign:'center'},countPill:{minWidth:28,height:20,borderRadius:10,paddingHorizontal:6,alignItems:'center',justifyContent:'center'},countText:{fontSize:11,fontWeight:'800'},search:{minHeight:50,borderWidth:1,borderRadius:14,flexDirection:'row',alignItems:'center',paddingLeft:13},searchInput:{flex:1,marginBottom:0,borderWidth:0,backgroundColor:'transparent'},heading:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',gap:10},sectionTitle:{fontSize:18,fontWeight:'900'},inlineButton:{flexDirection:'row',alignItems:'center'},viewAll:{fontSize:13,fontWeight:'800'},loading:{paddingVertical:24,textAlign:'center'},list:{padding:0,overflow:'hidden'},row:{minHeight:70,paddingHorizontal:8,paddingVertical:8,flexDirection:'row',alignItems:'center',gap:8},docIcon:{width:38,height:44,borderRadius:8,alignItems:'center',justifyContent:'center'},docTitle:{fontSize:13.5,fontWeight:'800',lineHeight:18},badge:{alignSelf:'flex-start',borderRadius:8,paddingHorizontal:7,paddingVertical:2,marginTop:4},date:{maxWidth:92,alignItems:'flex-end'},empty:{minHeight:92,padding:16,flexDirection:'row',alignItems:'center',gap:14},emptyTitle:{fontSize:16,fontWeight:'900',marginBottom:4},upload:{minHeight:72,borderWidth:1,borderRadius:14,padding:10,flexDirection:'row',alignItems:'center',gap:10},uploadIcon:{width:46,height:46,borderRadius:23,alignItems:'center',justifyContent:'center'},uploadTitle:{fontSize:14,fontWeight:'900',marginBottom:2},uploadButton:{height:38,borderWidth:1,borderRadius:8,paddingHorizontal:11,flexDirection:'row',alignItems:'center',gap:5},uploadButtonText:{fontSize:12,fontWeight:'800'},categories:{padding:12,gap:12},categoryGrid:{flexDirection:'row',flexWrap:'wrap',justifyContent:'space-between',gap:8},categoryCard:{minHeight:126,borderWidth:1,borderRadius:12,padding:10,gap:5},categoryTitle:{fontSize:13,fontWeight:'800',marginTop:2},progressTrack:{height:4,borderRadius:2,overflow:'hidden',marginTop:'auto'},progress:{height:4,borderRadius:2},picker:{minHeight:92,borderWidth:1.5,borderStyle:'dashed',borderRadius:16,padding:14,flexDirection:'row',alignItems:'center',gap:12},fileName:{fontSize:15,fontWeight:'900'},label:{fontSize:15,fontWeight:'900',marginTop:7},choices:{flexDirection:'row',flexWrap:'wrap',gap:7},choice:{width:'48%',flexGrow:1,minHeight:46,borderWidth:1,borderRadius:12,paddingHorizontal:10,flexDirection:'row',alignItems:'center',gap:7},choiceText:{flex:1,fontSize:12,fontWeight:'800'},visibility:{flexDirection:'row',gap:9}});
